<?php
declare(strict_types=1);
namespace App\Controllers;
use PDO;use App\Core\Auth;use App\Core\Database;use App\Core\Security;use App\Core\View;use App\Services\AuditService;use App\Services\NotificationService;use App\Services\PermissionService;use App\Services\WorkflowService;use App\Support\Jalali;
final class AdvancedController{
 private function guard(string $p):void{Auth::requireLogin();PermissionService::require(Auth::userId(),$p);}
 private function csv(array $rows,array $headers,string $name):never{
  header('Content-Type:text/csv;charset=UTF-8');header('Content-Disposition:attachment; filename="'.$name.'"');echo "\xEF\xBB\xBF";$o=fopen('php://output','wb');fputcsv($o,$headers);foreach($rows as $r)fputcsv($o,$r);fclose($o);exit;
 }
 public function search():void{$this->guard('search.view');$pdo=Database::connection();$q=trim((string)($_GET['q']??''));$category=(int)($_GET['category_id']??0);$unit=(int)($_GET['unit_id']??0);$importance=(int)($_GET['importance']??0);$status=(string)($_GET['status']??'active');$age=(int)($_GET['age']??0);$min=(string)($_GET['min_price']??'');$max=(string)($_GET['max_price']??'');$where=['1=1'];$p=[];if($q!==''){$where[]='(p.product_code LIKE :q OR p.product_name LIKE :q)';$p['q']='%'.$q.'%';}if($category){$where[]='p.category_id=:cat';$p['cat']=$category;}if($unit){$where[]='p.unit_id=:unit';$p['unit']=$unit;}if($importance){$where[]='p.importance=:imp';$p['imp']=$importance;}if($status==='active')$where[]="p.is_active=1";elseif($status==='inactive')$where[]="p.is_active=0";if($age>0){$where[]="EXISTS(SELECT 1 FROM product_prices ap WHERE ap.product_id=p.id AND ap.price_received_at<=DATEADD(DAY,-:age,SYSDATETIME()))";$p['age']=$age;}if($min!==''){$where[]="EXISTS(SELECT 1 FROM product_prices bp WHERE bp.product_id=p.id AND bp.unit_price>=:minp)";$p['minp']=(float)$min;}if($max!==''){$where[]="EXISTS(SELECT 1 FROM product_prices cp WHERE cp.product_id=p.id AND cp.unit_price<=:maxp)";$p['maxp']=(float)$max;}$sql="SELECT TOP 500 p.id,p.product_code,p.product_name,p.importance,p.is_active,p.status,c.name category_name,u.name unit_name,(SELECT MAX(x.price_received_at) FROM product_prices x WHERE x.product_id=p.id) latest_date,(SELECT MAX(x.unit_price) FROM product_prices x WHERE x.product_id=p.id) latest_unit_price FROM products p LEFT JOIN product_categories c ON c.id=p.category_id JOIN units u ON u.id=p.unit_id WHERE ".implode(' AND ',$where)." ORDER BY p.product_code";$s=$pdo->prepare($sql);$s->execute($p);$rows=$s->fetchAll();$categories=$pdo->query('SELECT id,name FROM product_categories WHERE is_active=1 ORDER BY name')->fetchAll();$units=$pdo->query('SELECT id,name FROM units WHERE is_active=1 ORDER BY name')->fetchAll();View::render('advanced/search',compact('rows','categories','units','q','category','unit','importance','status','age','min','max'));}
 public function bulk():void{$this->guard('products.bulk');$pdo=Database::connection();$rows=$pdo->query('SELECT TOP 500 id,product_code,product_name,importance,is_active FROM products ORDER BY product_code')->fetchAll();View::render('advanced/bulk',compact('rows'));}
 public function bulkApply():void{$this->guard('products.bulk');Security::verifyCsrf();$ids=array_values(array_filter(array_map('intval',(array)($_POST['ids']??[]))));$action=(string)($_POST['action']??'');if(!$ids)exit('حداقل یک محصول انتخاب کنید.');$pdo=Database::connection();$in=implode(',',array_fill(0,count($ids),'?'));$params=$ids;if($action==='activate'||$action==='deactivate'){$v=$action==='activate'?1:0;$s=$pdo->prepare("UPDATE products SET is_active=?,status=?,updated_at=SYSDATETIME() WHERE id IN ($in)");array_unshift($params,$v,$v?'active':'inactive');$s->execute($params);}elseif($action==='importance'){$v=max(1,min(3,(int)($_POST['importance']??1)));$s=$pdo->prepare("UPDATE products SET importance=?,updated_at=SYSDATETIME() WHERE id IN ($in)");array_unshift($params,$v);$s->execute($params);}else exit('عملیات نامعتبر است.');AuditService::log(Auth::userId(),'products.bulk', 'product', null,null,['action'=>$action,'ids'=>$ids]);Security::redirect('/products/bulk');}
 public function productSources(int $id):void{$this->guard('suppliers.view');$pdo=Database::connection();$s=$pdo->prepare('SELECT id,product_code,product_name FROM products WHERE id=:id');$s->execute(['id'=>$id]);$product=$s->fetch();if(!$product)exit('محصول یافت نشد.');$suppliers=$pdo->query('SELECT id,code,name,is_active FROM suppliers ORDER BY name')->fetchAll();$s=$pdo->prepare('SELECT ps.supplier_id,ps.source_no,ps.expected,ps.is_active FROM product_sources ps WHERE ps.product_id=:id');$s->execute(['id'=>$id]);$sources=[];foreach($s->fetchAll() as $r)$sources[(int)$r['supplier_id']]=$r;View::render('advanced/product-sources',compact('product','suppliers','sources'));}
 public function saveProductSources(int $id):void{$this->guard('suppliers.edit');Security::verifyCsrf();$pdo=Database::connection();$pdo->beginTransaction();try{$pdo->prepare('DELETE FROM product_sources WHERE product_id=:id')->execute(['id'=>$id]);$s=$pdo->prepare('INSERT INTO product_sources(product_id,supplier_id,source_no,expected,is_active) VALUES(:p,:s,:n,:e,1)');foreach((array)($_POST['sources']??[]) as $sid=>$r){$sid=(int)$sid;$n=max(1,min(99,(int)($r['source_no']??1)));$e=!empty($r['expected'])?1:0;if($sid>0)$s->execute(['p'=>$id,'s'=>$sid,'n'=>$n,'e'=>$e]);}$pdo->commit();}catch(\Throwable $e){$pdo->rollBack();throw $e;}AuditService::log(Auth::userId(),'product.sources.update','product',(string)$id);Security::redirect('/admin/product-sources/'.$id);}
 public function workflow():void{$this->guard('workflow.view');$pdo=Database::connection();$steps=$pdo->query('SELECT * FROM workflow_steps WHERE is_active=1 ORDER BY sort_order')->fetchAll();$rows=$pdo->query("SELECT TOP 300 p.id,p.product_code,p.product_name,w.id workflow_id,w.status workflow_status,s.name step_name,w.assigned_to,u.name assigned_name,w.comment,w.started_at,w.completed_at FROM products p LEFT JOIN price_workflow w ON w.id=(SELECT TOP 1 x.id FROM price_workflow x WHERE x.product_id=p.id ORDER BY x.created_at DESC) LEFT JOIN workflow_steps s ON s.id=w.step_id LEFT JOIN users u ON u.id=w.assigned_to WHERE p.is_active=1 ORDER BY p.product_code")->fetchAll();$users=$pdo->query('SELECT id,name FROM users WHERE is_active=1 ORDER BY name')->fetchAll();View::render('advanced/workflow',compact('rows','steps','users'));}
 public function workflowStart():void{$this->guard('workflow.manage');Security::verifyCsrf();$pid=(int)($_POST['product_id']??0);$step=(int)($_POST['step_id']??0);$uid=(int)($_POST['assigned_to']??0);$id=WorkflowService::start($pid,$step,$uid?:null);AuditService::log(Auth::userId(),'workflow.start','workflow',(string)$id);Security::redirect('/workflow');}
 public function workflowUpdate(int $id):void{$this->guard('workflow.manage');Security::verifyCsrf();$status=(string)($_POST['status']??'completed');$comment=trim((string)($_POST['comment']??''));$pdo=Database::connection();if($status==='completed')WorkflowService::complete($id,$comment);else{$s=$pdo->prepare('UPDATE price_workflow SET status=:s,comment=:c,updated_at=SYSDATETIME() WHERE id=:id');$s->execute(['s'=>$status,'c'=>$comment?:null,'id'=>$id]);}AuditService::log(Auth::userId(),'workflow.update','workflow',(string)$id,null,['status'=>$status,'comment'=>$comment]);Security::redirect('/workflow');}
 public function queueSettings():void{$this->guard('queue.settings');$keys=['queue.fresh_days'=>'سن پایه صف','queue.min_sources'=>'حداقل منابع','queue.spread_percent'=>'آستانه اختلاف درصد','queue.score_fresh_7'=>'امتیاز ۷ روز','queue.score_fresh_15'=>'امتیاز ۱۵ روز','queue.score_fresh_30'=>'امتیاز ۳۰ روز'];$pdo=Database::connection();$s=$pdo->query('SELECT setting_key,setting_value FROM system_settings')->fetchAll();$settings=[];foreach($s as $r)$settings[$r['setting_key']]=$r['setting_value'];View::render('advanced/queue-settings',compact('keys','settings'));}
 public function saveQueueSettings():void{$this->guard('queue.settings');Security::verifyCsrf();$pdo=Database::connection();foreach((array)($_POST['settings']??[]) as $k=>$v){$s=$pdo->prepare('MERGE system_settings AS t USING (SELECT :k setting_key,:v setting_value,:u updated_by) s ON t.setting_key=s.setting_key WHEN MATCHED THEN UPDATE SET setting_value=s.setting_value,updated_by=s.updated_by,updated_at=SYSDATETIME() WHEN NOT MATCHED THEN INSERT(setting_key,setting_value,updated_by) VALUES(s.setting_key,s.setting_value,s.updated_by);');$s->execute(['k'=>(string)$k,'v'=>(string)$v,'u'=>Auth::userId()]);}AuditService::log(Auth::userId(),'queue.settings.update','settings');Security::redirect('/admin/queue-settings');}
 public function health():void{$this->guard('system.health');$pdo=Database::connection();$tables=['products','product_prices','price_queue','price_workflow','suppliers','users','audit_logs','notifications','system_jobs','import_jobs'];$counts=[];foreach($tables as $t){$counts[$t]=(int)$pdo->query("SELECT COUNT(*) FROM dbo.[$t]")->fetchColumn();}$health=['php'=>PHP_VERSION,'pdo_sqlsrv'=>extension_loaded('pdo_sqlsrv')?'فعال':'غیرفعال','sqlsrv'=>extension_loaded('sqlsrv')?'فعال':'غیرفعال','session'=>session_status()===PHP_SESSION_ACTIVE?'فعال':'غیرفعال'];View::render('advanced/health',compact('counts','health'));}
 public function auditSearch():void{$this->guard('audit.view');$q=trim((string)($_GET['q']??''));$action=trim((string)($_GET['action']??''));$user=(int)($_GET['user_id']??0);$pdo=Database::connection();$where=['1=1'];$p=[];if($q!==''){$where[]='(a.entity_id LIKE :q OR a.entity_type LIKE :q OR a.action LIKE :q)';$p['q']='%'.$q.'%';}if($action!==''){$where[]='a.action LIKE :a';$p['a']='%'.$action.'%';}if($user){$where[]='a.user_id=:u';$p['u']=$user;}$s=$pdo->prepare("SELECT TOP 500 a.*,u.username FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id WHERE ".implode(' AND ',$where).' ORDER BY a.created_at DESC');$s->execute($p);$rows=$s->fetchAll();$users=$pdo->query('SELECT id,username FROM users ORDER BY username')->fetchAll();View::render('advanced/audit',compact('rows','users','q','action','user'));}
 public function export(string $type):never{$this->guard('reports.export');$pdo=Database::connection();switch($type){case'products':$rows=$pdo->query('SELECT p.product_code,p.product_name,u.name,p.importance,p.is_active,p.expected_sources,p.min_sources,p.max_sources,c.name FROM products p JOIN units u ON u.id=p.unit_id LEFT JOIN product_categories c ON c.id=p.category_id ORDER BY p.product_code')->fetchAll(PDO::FETCH_NUM);return $this->csv($rows,['کد','نام','واحد','اهمیت','فعال','منابع مورد انتظار','حداقل','حداکثر','دسته'],'products.csv');case'prices':$rows=$pdo->query('SELECT p.product_code,p.product_name,pp.source_no,pp.supplier,pp.package_price,pp.unit_price,pp.price_received_at FROM product_prices pp JOIN products p ON p.id=pp.product_id ORDER BY p.product_code,pp.price_received_at DESC')->fetchAll(PDO::FETCH_NUM);return $this->csv($rows,['کد','نام','منبع','تأمین‌کننده','قیمت بسته','قیمت واحد','تاریخ'],'prices.csv');case'queue':$rows=$pdo->query('SELECT p.product_code,p.product_name,q.score,q.priority_level,q.status,q.assigned_to,q.due_at,q.result_note FROM price_queue q JOIN products p ON p.id=q.product_id ORDER BY q.score DESC')->fetchAll(PDO::FETCH_NUM);return $this->csv($rows,['کد','نام','امتیاز','اولویت','وضعیت','مسئول','موعد','نتیجه'],'queue.csv');case'history':$rows=$pdo->query('SELECT p.product_code,p.product_name,pp.source_no,pp.supplier,pp.unit_price,pp.price_received_at FROM product_prices pp JOIN products p ON p.id=pp.product_id ORDER BY pp.price_received_at DESC')->fetchAll(PDO::FETCH_NUM);return $this->csv($rows,['کد','نام','منبع','تأمین‌کننده','قیمت واحد','تاریخ'],'history.csv');case'suppliers':$rows=$pdo->query('SELECT code,name,phone,email,contact_name,is_active FROM suppliers ORDER BY name')->fetchAll(PDO::FETCH_NUM);return $this->csv($rows,['کد','نام','تلفن','ایمیل','تماس','فعال'],'suppliers.csv');default:exit('نوع خروجی نامعتبر است.');}}
 public function excel(string $type):never{$this->guard('reports.export');$map=['products'=>'SELECT p.product_code,p.product_name,u.name unit_name,p.importance,p.is_active FROM products p JOIN units u ON u.id=p.unit_id ORDER BY p.product_code','prices'=>'SELECT p.product_code,p.product_name,pp.source_no,pp.supplier,pp.unit_price,pp.price_received_at FROM product_prices pp JOIN products p ON p.id=pp.product_id ORDER BY pp.price_received_at DESC','queue'=>'SELECT p.product_code,p.product_name,q.score,q.priority_level,q.status FROM price_queue q JOIN products p ON p.id=q.product_id ORDER BY q.score DESC'];$sql=$map[$type]??null;if(!$sql)exit('نوع خروجی نامعتبر است.');$rows=Database::connection()->query($sql)->fetchAll();header('Content-Type:application/vnd.ms-excel; charset=UTF-8');header('Content-Disposition:attachment; filename="'.$type.'.xls"');echo "<table border='1'><tr>";foreach(array_keys($rows[0]??[]) as $h)echo '<th>'.Security::e($h).'</th>';echo '</tr>';foreach($rows as $r){echo '<tr>';foreach($r as $v)echo '<td>'.Security::e($v).'</td>';echo '</tr>';}echo '</table>';exit;}
 public function generateNotifications():void{$this->guard('notifications.manage');Security::verifyCsrf();$pdo=Database::connection();$users=$pdo->query('SELECT id FROM users WHERE is_active=1')->fetchAll();$critical=(int)$pdo->query("SELECT COUNT(*) FROM price_queue WHERE priority_level='critical' AND status IN('new','in_progress','needs_followup')")->fetchColumn();$old=(int)$pdo->query("SELECT COUNT(*) FROM products p WHERE p.is_active=1 AND NOT EXISTS(SELECT 1 FROM product_prices pp WHERE pp.product_id=p.id)")->fetchColumn();foreach($users as $u){if($critical)NotificationService::create((int)$u['id'],'critical','اولویت بحرانی','تعداد '.$critical.' آیتم بحرانی در صف وجود دارد.');if($old)NotificationService::create((int)$u['id'],'missing_price','محصول بدون قیمت','تعداد '.$old.' محصول بدون قیمت وجود دارد.');}AuditService::log(Auth::userId(),'notifications.generate');Security::redirect('/notifications');}
 public function sessions():void{$this->guard('security.manage');$pdo=Database::connection();$rows=$pdo->query('SELECT s.id,s.user_id,s.ip_address,s.user_agent,s.created_at,s.last_seen_at,s.expires_at,u.username,u.name FROM active_sessions s JOIN users u ON u.id=s.user_id WHERE s.revoked_at IS NULL AND (s.expires_at IS NULL OR s.expires_at>SYSDATETIME()) ORDER BY s.last_seen_at DESC')->fetchAll();View::render('advanced/sessions',compact('rows'));}
 public function revokeSession(int $id):void{$this->guard('security.manage');Security::verifyCsrf();$s=Database::connection()->prepare('UPDATE active_sessions SET revoked_at=SYSDATETIME() WHERE id=:id');$s->execute(['id'=>$id]);AuditService::log(Auth::userId(),'session.revoke','session',(string)$id);Security::redirect('/admin/sessions');}
 public function notificationSettings():void{$this->guard('notifications.manage');$rows=Database::connection()->query('SELECT * FROM notification_rules ORDER BY rule_key')->fetchAll();View::render('advanced/notification-settings',compact('rows'));}
 public function saveNotificationSettings():void{$this->guard('notifications.manage');Security::verifyCsrf();$pdo=Database::connection();foreach((array)($_POST['rules']??[]) as $k=>$v){$s=$pdo->prepare('UPDATE notification_rules SET is_enabled=:e,channel=:c,updated_by=:u,updated_at=SYSDATETIME() WHERE rule_key=:k');$s->execute(['e'=>!empty($v['enabled'])?1:0,'c'=>in_array(($v['channel']??'panel'),['panel','email'],true)?$v['channel']:'panel','u'=>Auth::userId(),'k'=>(string)$k]);}AuditService::log(Auth::userId(),'notification.settings.update');Security::redirect('/admin/notification-settings');}

 public function importAdvanced():void{$this->guard('imports.view');View::render('advanced/import');}
 public function importAdvancedPost():void{$this->guard('imports.manage');Security::verifyCsrf();$type=(string)($_POST['type']??'');if(empty($_FILES['file']['tmp_name']))exit('فایل انتخاب نشده است.');$h=fopen($_FILES['file']['tmp_name'],'rb');$head=fgetcsv($h);$map=[];foreach((array)$head as $k=>$v)$map[trim((string)$v)]=$k;$ok=0;$err=0;$details=[];$pdo=Database::connection();$n=0;while(($row=fgetcsv($h))!==false){$n++;try{if($type==='prices'){foreach(['product_code','source_no','supplier','package_price','unit_price','price_received_at'] as $x)if(!isset($map[$x]))throw new \RuntimeException('ستون '.$x.' الزامی است.');$code=trim((string)$row[$map['product_code']]);$s=$pdo->prepare('SELECT id FROM products WHERE product_code=:c');$s->execute(['c'=>$code]);$pid=$s->fetchColumn();if($pid===false)throw new \RuntimeException('محصول '.$code.' یافت نشد.');$date=trim((string)$row[$map['price_received_at']]);if(preg_match('/^\\d{4}[-\\/]\\d{1,2}[-\\/]\\d{1,2}$/',$date))$date=Jalali::toGregorian($date);$s=$pdo->prepare('INSERT INTO product_prices(product_id,source_no,supplier,package_price,unit_price,price_received_at,created_by,created_at,updated_at) VALUES(:p,:n,:s,:pp,:up,:d,:u,SYSDATETIME(),SYSDATETIME())');$s->execute(['p'=>$pid,'n'=>(int)$row[$map['source_no']],'s'=>trim((string)$row[$map['supplier']]),'pp'=>(float)$row[$map['package_price']],'up'=>(float)$row[$map['unit_price']],'d'=>$date,'u'=>Auth::userId()]);}elseif($type==='suppliers'){$name=trim((string)($row[$map['name']]??''));if($name==='')throw new \RuntimeException('نام تأمین‌کننده الزامی است.');$s=$pdo->prepare('INSERT INTO suppliers(code,name,phone,email,contact_name,notes) VALUES(:c,:n,:p,:e,:cn,:no)');$s->execute(['c'=>trim((string)($row[$map['code']]??''))?:null,'n'=>$name,'p'=>trim((string)($row[$map['phone']]??''))?:null,'e'=>trim((string)($row[$map['email']]??''))?:null,'cn'=>trim((string)($row[$map['contact_name']]??''))?:null,'no'=>trim((string)($row[$map['notes']]??''))?:null]);}else throw new \RuntimeException('نوع Import نامعتبر است.');$ok++;}catch(\Throwable $e){$err++;$details[]='ردیف '.$n.': '.$e->getMessage();}}fclose($h);AuditService::log(Auth::userId(),'import.advanced',null,null,null,['type'=>$type,'success'=>$ok,'errors'=>$err]);View::render('management/import-result',['result'=>['total'=>$ok+$err,'success'=>$ok,'errors'=>$err,'details'=>$details]]);}

 public function saveFilter():void{$this->guard('search.view');Security::verifyCsrf();$name=trim((string)($_POST['name']??''));$json=(string)($_POST['filter_json']??'{}');if($name==='')exit('نام فیلتر الزامی است.');$s=Database::connection()->prepare('INSERT INTO saved_filters(user_id,name,screen,filter_json) VALUES(:u,:n,:s,:j)');$s->execute(['u'=>Auth::userId(),'n'=>$name,'s'=>'search','j'=>$json]);Security::redirect('/search');}
 public function deleteFilter(int $id):void{$this->guard('search.view');Security::verifyCsrf();$s=Database::connection()->prepare('DELETE FROM saved_filters WHERE id=:id AND user_id=:u');$s->execute(['id'=>$id,'u'=>Auth::userId()]);Security::redirect('/search');}

}
